	"github.com/cocosolocoder/signalroom/internal/events"
)

var errFaultInjectionUnsupported = errors.New("deterministic fault injection unsupported on this platform")

func testEvent(id string, at time.Time) events.Event {
	return events.Event{ID: id, Service: "svc", Severity: "info", Message: "msg-" + id, At: at}
}

func TestAppendAndReopen(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)

	log, batches, err := Open(dir)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	if err := log.Append([]events.Event{testEvent("a", base), testEvent("b", base.Add(time.Second))}); err != nil {
		t.Fatalf("append: %v", err)
	}
	if err := log.Append([]events.Event{testEvent("c", base.Add(2 * time.Second))}); err != nil {
		t.Fatalf("append: %v", err)
	}
	if err := log.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}

	log2, batches, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer log2.Close()
	if len(batches) != 2 || len(batches[0]) != 2 || len(batches[1]) != 1 {
		t.Fatalf("unexpected recovered batches: %+v", batches)
	}
	flat := []string{batches[0][0].ID, batches[0][1].ID, batches[1][0].ID}
	if strings.Join(flat, ",") != "a,b,c" {
		t.Fatalf("recovery order: %v", flat)
	}
	if !batches[0][0].At.Equal(base) {
		t.Fatalf("timestamp not preserved absolutely: %v", batches[0][0].At)
	}

	// A new batch after recovery appends cleanly and reads back as frame 3.
	if err := log2.Append([]events.Event{testEvent("d", base.Add(3 * time.Second))}); err != nil {
		t.Fatalf("append after recovery: %v", err)
	}
	if err := log2.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	_, batches, err = Open(dir)
	if err != nil {
		t.Fatalf("reopen 2: %v", err)
	}
	if len(batches) != 3 || batches[2][0].ID != "d" {
		t.Fatalf("post-tail-write corrupted recovery: %+v", batches)
	}
}

func TestReplayIgnoresTornTailOnly(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	path := filepath.Join(dir, logName)

	log, _, err := Open(dir)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
		t.Fatalf("append: %v", err)
	}
	if err := log.Append([]events.Event{testEvent("b", base.Add(time.Second))}); err != nil {
		t.Fatalf("append: %v", err)
	}
	log.Close()

	good, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read: %v", err)
	}

	// Torn payload: full header promising more bytes than exist.
	payload, _ := events.MarshalBatch([]events.Event{testEvent("torn", base.Add(2*time.Second))})
	partialHeader := make([]byte, 5) // also exercises a short partial header
	binary.BigEndian.PutUint32(partialHeader[0:4], uint32(len(payload)))

	cases := map[string][]byte{
		"partial header":  partialHeader,
		"partial payload": frameFor(payload)[:headerSize+3],
		"full header only": func() []byte {
			b := make([]byte, headerSize)
			binary.BigEndian.PutUint32(b[0:4], uint32(len(payload)))
			binary.BigEndian.PutUint32(b[4:8], crc32.ChecksumIEEE(payload))
			return b
		}(),
	}
	for name, tail := range cases {
		t.Run(name, func(t *testing.T) {
			if err := os.WriteFile(path, append(append([]byte(nil), good...), tail...), 0o644); err != nil {
				t.Fatalf("seed torn file: %v", err)
			}
			log2, batches, err := Open(dir)
			if err != nil {
				t.Fatalf("torn tail must be tolerated: %v", err)
			}
			if len(batches) != 2 {
				t.Fatalf("want 2 intact batches, got %d", len(batches))
			}
			// Ignored tail must not pollute the next write.
			if err := log2.Append([]events.Event{testEvent("after", base.Add(3 * time.Second))}); err != nil {
				t.Fatalf("append over torn tail: %v", err)
			}
			log2.Close()

			_, recovered, err := Open(dir)
			if err != nil {
				t.Fatalf("reopen: %v", err)
			}
			if len(recovered) != 3 || recovered[2][0].ID != "after" {
				t.Fatalf("tail leaked into later frames: %+v", recovered)
			}
		})
	}
}

// frameFor wraps a payload the same way Log.Append does.
func frameFor(payload []byte) []byte {
	frame := make([]byte, headerSize+len(payload))
	binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
	binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
	copy(frame[headerSize:], payload)
	return frame
}

func TestReplayFailsOnMidCorruption(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	path := filepath.Join(dir, logName)

	log, _, err := Open(dir)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
		t.Fatalf("append: %v", err)
	}
	log.Close()

	original, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	firstFrameLen := headerSize + int(binary.BigEndian.Uint32(original[0:4]))

	// A complete-looking second frame with a bad checksum.
	payload, _ := events.MarshalBatch([]events.Event{testEvent("x", base.Add(time.Second))})
	bad := frameFor(payload)
	bad[headerSize] ^= 0xFF
	corrupt := append(append([]byte(nil), original[:firstFrameLen]...), bad...)
	if err := os.WriteFile(path, corrupt, 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}

	if _, _, err := Open(dir); !isCorruption(err) {
		t.Fatalf("mid corruption must fail startup, got %v", err)
	}
	if after, _ := os.ReadFile(path); string(after) != string(corrupt) {
		t.Fatal("failed startup must not modify the data file")
	}
}

func isCorruption(err error) bool {
	var target *CorruptionError
	return errors.As(err, &target)
}

func TestReplayFailsOnCompleteIllegalFrame(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	path := filepath.Join(dir, logName)

	log, _, err := Open(dir)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
		t.Fatalf("append: %v", err)
	}
	log.Close()

	original, _ := os.ReadFile(path)
	firstFrameLen := headerSize + int(binary.BigEndian.Uint32(original[0:4]))

	// Complete frame with valid checksum carrying an unknown field.
	illegal := []byte(`[{"id":"z","service":"s","severity":"info","message":"m","at":"2026-10-01T09:00:01Z","bogus":true}]`)
	withIllegal := append(append([]byte(nil), original[:firstFrameLen]...), frameFor(illegal)...)
	if err := os.WriteFile(path, withIllegal, 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}
	// A complete frame containing an empty batch is also illegal.
	withEmpty := append(append([]byte(nil), original[:firstFrameLen]...), frameFor([]byte("[]"))...)
	if err := os.WriteFile(path, withEmpty, 0o644); err != nil {
		t.Fatalf("write empty frame: %v", err)
	}
	if _, _, err := Open(dir); !isCorruption(err) {
		t.Fatalf("empty frame must fail startup, got %v", err)
	}
}

func TestAppendFailurePoisonsLog(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)

	log, _, err := Open(dir)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
		t.Fatalf("append: %v", err)
	}
	if err := breakWriter(log); err != nil {
		if errors.Is(err, errFaultInjectionUnsupported) {
			t.Skip("deterministic write fault injection requires /dev/full")
		}
		t.Fatalf("inject fault: %v", err)
	}

	err = log.Append([]events.Event{testEvent("b", base.Add(time.Second))})
	if err == nil {
		t.Fatal("write failure must return an error")
	}
	if !errors.Is(err, ErrPoisoned) {
		t.Fatalf("write failure must surface ErrPoisoned, got %v", err)
	}
	for range 3 {
		if err := log.Append([]events.Event{testEvent("c", base.Add(2 * time.Second))}); !errors.Is(err, ErrPoisoned) {
			t.Fatalf("later writes must return ErrPoisoned, got %v", err)
		}
	}
}

func breakWriter(log *Log) error {
	full, err := os.OpenFile("/dev/full", os.O_WRONLY, 0)
	if err != nil {
		if os.IsNotExist(err) {
			return errFaultInjectionUnsupported
		}
		return err
	}
	log.mu.Lock()
	old := log.file
	log.file = full
	log.mu.Unlock()
	return old.Close()
}

func TestDirectoryLockExclusiveAndReusable(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)

	first, _, err := Open(dir)
	if err != nil {
		t.Fatalf("first open: %v", err)
	}
	if err := first.Append([]events.Event{testEvent("a", base)}); err != nil {
		t.Fatalf("append: %v", err)
	}

	second, batches, err := Open(dir)
	if err == nil {
		second.Close()
		t.Fatal("second instance must fail while the first holds the directory")
	}
	if batches != nil {
		t.Fatal("failed second open must not return recovered data")
	}
	if !strings.Contains(err.Error(), "in use") {
		t.Fatalf("error should explain the directory is in use, got: %v", err)
	}

	// Data written before the failed takeover must be intact.
	if onDisk, _ := os.ReadFile(filepath.Join(dir, logName)); !strings.Contains(string(onDisk), `"a"`) {
		t.Fatal("rejected second instance must not change data")
	}

	if err := first.Close(); err != nil {
		t.Fatalf("close first: %v", err)
	}

	third, batches, err := Open(dir)
	if err != nil {
		t.Fatalf("restart after clean exit must succeed: %v", err)
	}
	defer third.Close()
	if len(batches) != 1 || batches[0][0].ID != "a" {
		t.Fatalf("restart must recover prior data: %+v", batches)
	}
}

package events

import (
	"errors"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func mkEvent(id, service, severity, message string, at time.Time) Event {
	return Event{ID: id, Service: service, Severity: severity, Message: message, At: at}
}

func TestIngestCreatesAndReplays(t *testing.T) {
	tl := NewTimeline()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	batch := []Event{
		mkEvent("evt-2", "checkout", " WARN ", " latency ", base.Add(time.Minute)),
		mkEvent("evt-1", "gateway", "CRITICAL", "spike", base),
	}
	var persisted []Event
	res, err := tl.Ingest(batch, func(created []Event) error {
		persisted = append(persisted, created...)
		return nil
	})
	if err != nil {
		t.Fatalf("ingest: %v", err)
	}
	if res.Created != 2 || res.Replayed != 0 {
		t.Fatalf("unexpected result: %+v", res)
	}
	if len(persisted) != 2 {
		t.Fatalf("commit hook got %d events", len(persisted))
	}
	if persisted[0].Severity != "warn" || persisted[0].Service != "checkout" {
		t.Fatalf("normalization not applied before commit: %+v", persisted[0])
	}

	// Identical retry, even with different formatting, is fully replayed.
	retry := []Event{
		mkEvent("  evt-1  ", "gateway", "critical", "spike", base),
		mkEvent("evt-2", " checkout ", "warn", "latency", base.Add(time.Minute)),
	}
	res, err = tl.Ingest(retry, func(created []Event) error {
		t.Fatalf("nothing should be persisted on replay, got %v", created)
		return nil
	})
	if err != nil {
		t.Fatalf("replay: %v", err)
	}
	if res.Created != 0 || res.Replayed != 2 {
		t.Fatalf("unexpected replay result: %+v", res)
	}

	all := tl.Query(Query{})
	if len(all) != 2 || all[0].ID != "evt-1" || all[1].ID != "evt-2" {
		t.Fatalf("timeline not ordered by time then id: %+v", all)
	}
}

func TestIngestAbsoluteTimeEquality(t *testing.T) {
	tl := NewTimeline()
	at := time.Date(2026, 10, 1, 10, 0, 0, 0, time.UTC)
	sameInstant := at.In(time.FixedZone("CST", 8*60*60))
	if !at.Equal(sameInstant) {
		t.Fatal("test setup: instants differ")
	}
	if _, err := tl.Ingest([]Event{mkEvent("e", "s", "info", "m", at)}, nil); err != nil {
		t.Fatalf("ingest: %v", err)
	}
	res, err := tl.Ingest([]Event{mkEvent("e", "s", "info", "m", sameInstant)}, nil)
	if err != nil {
		t.Fatalf("same instant in another zone should replay: %v", err)
	}
	if res.Replayed != 1 {
		t.Fatalf("want replay, got %+v", res)
	}

	other := sameInstant.Add(time.Nanosecond)
	_, err = tl.Ingest([]Event{mkEvent("e", "s", "info", "m", other)}, nil)
	if !IsConflictError(err) {
		t.Fatalf("different instant should conflict, got %v", err)
	}
}

func TestIngestValidationPrecedesConflicts(t *testing.T) {
	tl := NewTimeline()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	_, err := tl.Ingest([]Event{mkEvent("dup", "s", "info", "old", base)}, nil)
	if err != nil {
		t.Fatalf("seed: %v", err)
	}

	called := false
	commit := func(created []Event) error { called = true; return nil }

	// Conflict present, but an invalid event comes first: validation wins.
	batch := []Event{
		mkEvent("dup", "s", "info", "different", base),
		mkEvent("bad", "s", "info", "   ", base),
	}
	_, err = tl.Ingest(batch, commit)
	if !IsValidationError(err) {
		t.Fatalf("want validation error, got %v", err)
	}
	if called {
		t.Fatal("commit hook must not run on validation failure")
	}

	// Pure conflict once the batch is valid.
	_, err = tl.Ingest([]Event{mkEvent("dup", "s", "info", "different", base)}, commit)
	if !IsConflictError(err) {
		t.Fatalf("want conflict error, got %v", err)
	}
	if called {
		t.Fatal("commit hook must not run on conflict")
	}
	if got := tl.Query(Query{}); len(got) != 1 || got[0].Message != "old" {
		t.Fatalf("rejected batch changed data: %+v", got)
	}
}

func TestIngestRejectsDuplicateIDWithinBatch(t *testing.T) {
	tl := NewTimeline()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	cases := [][]Event{
		{mkEvent("a", "s", "info", "one", base), mkEvent("a", "s", "info", "one", base)},
		{mkEvent(" a ", "s", "info", "one", base), mkEvent("a", "s2", "info", "two", base)},
	}
	for i, batch := range cases {
		if _, err := tl.Ingest(batch, nil); !IsConflictError(err) {
			t.Fatalf("case %d: want conflict, got %v", i, err)
		}
	}
	if got := tl.Query(Query{}); len(got) != 0 {
		t.Fatalf("rejected batches must not store anything: %+v", got)
	}
}

func TestIngestCommitFailureRejectsBatch(t *testing.T) {
	tl := NewTimeline()
	base := time.Now()
	want := errors.New("disk gone")
	_, err := tl.Ingest([]Event{mkEvent("e", "s", "info", "m", base)}, func(created []Event) error {
		return want
	})
	if !errors.Is(err, want) {
		t.Fatalf("want commit error propagated, got %v", err)
	}
	if got := tl.Query(Query{}); len(got) != 0 {
		t.Fatalf("failed commit must not be visible: %+v", got)
	}
}

func TestTimelineQueryFiltersAndOrder(t *testing.T) {
	tl := NewTimeline()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	batch := []Event{
		mkEvent("c", "gateway", "info", "c", base.Add(2*time.Minute)),
		mkEvent("a", "gateway", "critical", "a", base),
		mkEvent("b", "api", "critical", "b", base),
		mkEvent("d", "api", "info", "d", base.Add(time.Minute)),
	}
	if _, err := tl.Ingest(batch, nil); err != nil {
		t.Fatalf("ingest: %v", err)
	}

	got := tl.Query(Query{Service: "gateway"})
	if ids(got) != "a,c" {
		t.Fatalf("service filter: %s", ids(got))
	}
	got = tl.Query(Query{Severity: " CRITICAL "})
	if ids(got) != "a,b" {
		t.Fatalf("severity filter (same-time tie by id): %s", ids(got))
	}
	got = tl.Query(Query{Since: base.Add(30 * time.Second), Until: base.Add(90 * time.Second)})
	if ids(got) != "d" {
		t.Fatalf("inclusive range: %s", ids(got))
	}
}

func ids(events []Event) string {
	parts := make([]string, len(events))
	for i, e := range events {
		parts[i] = e.ID
	}
	return strings.Join(parts, ",")
}

func TestIngestConcurrentSameContent(t *testing.T) {
	tl := NewTimeline()
	at := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	var commits int64
	commit := func(created []Event) error {
		atomic.AddInt64(&commits, 1)
		return nil
	}

	const n = 64
	start := make(chan struct{})
	var wg sync.WaitGroup
	var created, replayed, failures int64
	for range n {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			res, err := tl.Ingest([]Event{mkEvent("same", "svc", "info", "body", at)}, commit)
			if err != nil {
				atomic.AddInt64(&failures, 1)
				return
			}
			atomic.AddInt64(&created, int64(res.Created))
			atomic.AddInt64(&replayed, int64(res.Replayed))
		}()
	}
	close(start)
	wg.Wait()

	if failures != 0 {
		t.Fatalf("identical concurrent posts must all succeed, failures=%d", failures)
	}
	if created != 1 || replayed != n-1 || atomic.LoadInt64(&commits) != 1 {
		t.Fatalf("created=%d replayed=%d commits=%d", created, replayed, commits)
	}
	if got := tl.Query(Query{}); len(got) != 1 {
		t.Fatalf("exactly one event must be stored, got %d", len(got))
	}
}

func TestIngestConcurrentConflictingContent(t *testing.T) {
	tl := NewTimeline()
	at := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)

	const n = 64
	start := make(chan struct{})
	var wg sync.WaitGroup
	var wins, conflicts int64
	for i := range n {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			_, err := tl.Ingest(
				[]Event{mkEvent("same", "svc", "info", "body-"+strconv.Itoa(i), at)},
				func(created []Event) error {
					atomic.AddInt64(&wins, 1)
					return nil
				},
			)
			if IsConflictError(err) {
				atomic.AddInt64(&conflicts, 1)
			} else if err != nil {
				t.Errorf("unexpected error: %v", err)
			}
		}()
	}
	close(start)
	wg.Wait()

	if wins != 1 || conflicts != n-1 {
		t.Fatalf("want exactly one winner, got wins=%d conflicts=%d", wins, conflicts)
	}
	got := tl.Query(Query{})
	if len(got) != 1 || !strings.HasPrefix(got[0].Message, "body-") {
		t.Fatalf("one version must be stored, got %+v", got)
	}
}

