package main

import (
	"bufio"
	"bytes"
	"context"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"hash/crc32"
	"io"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"
)

var (
	binaryPath string
	buildOnce  sync.Once
	buildErr   error
)

func TestMain(m *testing.M) {
	buildOnce.Do(func() {
		dir, err := os.MkdirTemp("", "signalroom-build-")
		if err != nil {
			buildErr = err
			return
		}
		binaryPath = filepath.Join(dir, "signalroom")
		buildErr = exec.Command("go", "build", "-o", binaryPath, ".").Run()
	})
	if buildErr != nil {
		fmt.Fprintln(os.Stderr, "build test binary:", buildErr)
		os.Exit(1)
	}
	os.Exit(m.Run())
}

type serverProc struct {
	cmd  *exec.Cdm
	addr string
	logs *safeBuffer
}

type safeBuffer struct {
	mu  sync.Mutex
	buf bytes.Buffer
}

func (s *safeBuffer) Write(p []byte) (int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.buf.Write(p)
}

func (s *safeBuffer) String() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.buf.String()
}

// startServer launches serve on an ephemeral port and blocks until the
// readiness line publishes the real address — no fixed sleeps.
func startServer(t *testing.T, dataDir string) *serverProc {
	t.Helper()
	logs := &safeBuffer{}
	cmd := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		t.Fatal(err)
	}
	cmd.Stderr = nil
	stderr, err := cmd.StderrPipe()
	if err != nil {
