1	// Package httpapi exposes the event timeline over HTTP.
2	package httpapi
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"errors"
8		"io"
9		"net/http"
10		"time"
11	
12		"github.com/cocosolocoder/signalroom/internal/events"
13	)
14	
15	// maxBodyBytes bounds a single POST /events request.
16	const maxBodyBytes = 16 << 20
17	
18	// Storage durably persists a batch before it becomes visible.
19	type Storage interface {
20		Append(batch []events.Event) error
21		Poisoned() bool
22	}
23	
24	type envelope struct {
25		Events json.RawMessage `json:"events"`
26	}
27	
28	// Handler wires the timeline and its durable log to HTTP routes.
29	type Handler struct {
30		timeline *events.Timeline
31		log      Storage
32		mux      *http.ServeMux
33	}
34	
35	// NewHandler builds the HTTP handler for a timeline backed by log.
36	func NewHandler(timeline *events.Timeline, log Storage) *Handler {
37		h := &Handler{timeline: timeline, log: log, mux: http.NewServeMux()}
38		h.mux.HandleFunc("/events", h.events)
39		h.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
40			writeError(w, http.StatusNotFound, "not found")
41		})
42		return h
43	}
44	
45	func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
46		h.mux.ServeHTTP(w, r)
47	}
48	
49	func (h *Handler) unavailable() bool {
50		return h.log.Poisoned()
51	}
52	
53	func (h *Handler) events(w http.ResponseWriter, r *http.Request) {
54		switch r.Method {
55		case http.MethodPost:
56			h.postEvents(w, r)
57		case http.MethodGet:
58			h.getEvents(w, r)
59		default:
60			w.Header().Set("Allow", "GET, POST")
61			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
62		}
63	}
64	
65	func (h *Handler) postEvents(w http.ResponseWriter, r *http.Request) {
66		if h.unavailable() {
67			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
68			return
69		}
70	
71		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
72		if err != nil {
73			writeError(w, http.StatusBadRequest, "invalid JSON body")
74			return
75		}
76	
77		dec := json.NewDecoder(bytes.NewReader(body))
78		dec.DisallowUnknownFields()
79		var input envelope
80		if err := dec.Decode(&input); err != nil {
81			writeError(w, http.StatusBadRequest, "invalid JSON body")
82			return
83		}
84		var extra json.RawMessage
85		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
86			writeError(w, http.StatusBadRequest, "invalid JSON body")
87			return
88		}
89		if len(bytes.TrimSpace(input.Events)) == 0 {
90			writeError(w, http.StatusBadRequest, "events must be a non-empty array")
91			return
92		}
93	
